const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const requestText = String(body.contract_request || body.request || body.message || 'definir contrato compartido para la HU');
const backlogId = String(body.backlog_id || body.backlogId || 'UNKNOWN').toUpperCase();
const discoveryRef = String(body.discovery_ref || body.discoveryRef || ('project/agent-work/' + backlogId + '/discovery.yaml'));
const dryRun = body.dry_run !== false;
const prompt = [
  'Actua como AGENT-CONTRACT-001 para el proyecto Invernadero Central.',
  'Solicitud: ' + requestText + '.',
  'backlog_id: ' + backlogId + '.',
  'Discovery esperado o referencia: ' + discoveryRef + '.',
  'Define un unico Shared Contract solo si Discovery indica API, MQTT, evento, schema, persistencia o frontera compartida frontend/backend/edge.',
  'Empieza por contratos existentes y convenciones actuales. Define delta exacto, compatibilidad, breaking changes, migraciones, error contract y cross-layer integrity.',
  'Incluye secciones solo cuando apliquen: domain_models_schema_delta, file_delta, http_api_contract, mqtt_event_contract, persistence_contract, compatibility_assessment, error_contract, non_functional_contract, unresolved_contract_decisions.',
  'No inventes endpoints, campos, eventos, tablas, DTOs, SLA ni comandos. Usa TBD si requiere decision humana.',
  'Trabaja en modo DRAFT/read-only; no persistas, no muevas Kanban, no marques DONE, no edites HU congeladas, no compres, no despliegues criticamente ni controles sistemas fisicos sin aprobacion humana.',
  'Si falta Discovery o una decision de contrato indispensable, haz una sola pregunta.'
].join(' ');
return [{ json: { agent: 'project-contract', workspace: 'central', prompt, mode: 'wf-shared-contract-001', approval_required: true, dry_run: dryRun, metadata: { task_id: 'WF-SHARED-CONTRACT-001', agent_id: 'AGENT-CONTRACT-001', backlog_id: backlogId, discovery_ref: discoveryRef, requested_by: body.requested_by || 'chat-gateway' } } }];
